# Point :: 
from dataclasses import dataclass

@dataclass(frozen=True)
class Point:
    x: float
    y: float
    def distance_to(self, other):
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5

if __name__ == "__main__":
    p = Point(0.0, 0.0)
    q = Point(3.0, 4.0)
    print(p.distance_to(q))

